-- Remove cross-contaminated suffix-only IDs from five PROPERTY pools.
-- For each pool its remaining property rows/weights exactly match paired
-- SkyFire 26.002. All 19 removed IDs are absent ItemRandomProperties.dbc,
-- and exist only in ItemRandomSuffix.dbc; no valid property row is removed.
-- A per-pool count/weight fingerprint prevents changing a customized pool.
CREATE TEMPORARY TABLE IF NOT EXISTS enchant_pool_repair_guard (entry INT PRIMARY KEY);
DELETE FROM enchant_pool_repair_guard;
INSERT INTO enchant_pool_repair_guard SELECT entry FROM item_enchantment_template WHERE entry=458 AND type=0 GROUP BY entry HAVING COUNT(*)=30 AND SUM((ench=31 AND ROUND(chance,4)=0.1) OR (ench=152 AND ROUND(chance,4)=4.44) OR (ench=153 AND ROUND(chance,4)=5.24) OR (ench=154 AND ROUND(chance,4)=3.4) OR (ench=174 AND ROUND(chance,4)=4.44) OR (ench=179 AND ROUND(chance,4)=5.24) OR (ench=184 AND ROUND(chance,4)=3.4) OR (ench=272 AND ROUND(chance,4)=35.5) OR (ench=273 AND ROUND(chance,4)=31.9) OR (ench=274 AND ROUND(chance,4)=32.6) OR (ench=683 AND ROUND(chance,4)=0.1) OR (ench=763 AND ROUND(chance,4)=6.15) OR (ench=764 AND ROUND(chance,4)=6.15) OR (ench=765 AND ROUND(chance,4)=6.15) OR (ench=766 AND ROUND(chance,4)=6.15) OR (ench=848 AND ROUND(chance,4)=3.32) OR (ench=849 AND ROUND(chance,4)=3.32) OR (ench=850 AND ROUND(chance,4)=3.32) OR (ench=851 AND ROUND(chance,4)=3.32) OR (ench=1018 AND ROUND(chance,4)=4.41) OR (ench=1019 AND ROUND(chance,4)=4.41) OR (ench=1020 AND ROUND(chance,4)=4.41) OR (ench=1021 AND ROUND(chance,4)=4.41) OR (ench=1022 AND ROUND(chance,4)=3.58) OR (ench=1805 AND ROUND(chance,4)=3.4) OR (ench=1806 AND ROUND(chance,4)=3.4) OR (ench=1843 AND ROUND(chance,4)=2.11) OR (ench=1844 AND ROUND(chance,4)=2.11) OR (ench=1957 AND ROUND(chance,4)=3.2) OR (ench=1958 AND ROUND(chance,4)=3.2))=30;
